<template><FormSection id="network" :title="t('settings.mirror_config')" :description="t('mirror.connectivity_description')"><div v-for="(value,name) in config" :key="name" class="mirror" :data-mirror="name"><div><StatusBadge :tone="role(name,value)==='official'?'info':'neutral'">{{t(`mirror.role_${role(name,value)}`)}}</StatusBadge> <strong>{{name}}</strong></div><label :for="`mirror-${name}`">{{t('mirror.url')}}</label><input :id="`mirror-${name}`" :value="value" @input="$emit('update',name,$event.target.value)"><div class="result"><template v-if="results[name]&&results[name].url===value"><StatusBadge :tone="results[name].success?'success':'error'">{{t(results[name].success?'mirror.connectivity_passed':'mirror.connectivity_failed')}}</StatusBadge><span v-if="results[name].latency!=null">{{results[name].latency}} ms</span><time v-if="results[name].lastChecked">{{t('mirror.last_checked')}}: {{formatTime(results[name].lastChecked)}}</time></template></div><button data-action="mirror-test" type="button" @click="$emit('test',name,value)">{{t('btn.test')}}</button><ConfirmAction :title="t('mirror.remove_title')" :description="value" :confirm-label="t('btn.remove')" :cancel-label="t('btn.cancel')" @confirm="$emit('remove',name)"><template #trigger><button data-action="mirror-remove" type="button">{{t('btn.remove')}}</button></template></ConfirmAction></div><div class="add"><label for="new-mirror-tool">{{t('settings.mirror_tool_placeholder')}}</label><input id="new-mirror-tool" v-model="tool"><label for="new-mirror-url">{{t('mirror.url')}}</label><input id="new-mirror-url" v-model="url"><p v-if="error" role="alert">{{t(error)}}</p><button type="button" data-action="mirror-add" :disabled="!tool||!url" @click="add">{{t('btn.add')}}</button></div><template #actions><button type="button" data-action="mirror-save" @click="save">{{t('settings.save_mirrors')}}</button></template></FormSection></template>
<script setup>import{ref}from'vue';import FormSection from'../FormSection.vue';import StatusBadge from'../StatusBadge.vue';import ConfirmAction from'../ConfirmAction.vue';const props=defineProps({config:{type:Object,default:()=>({})},results:{type:Object,default:()=>({})},locale:{type:String,default:'en'},t:{type:Function,required:true}});const emit=defineEmits(['update','test','remove','add','save']);const tool=ref(''),url=ref(''),error=ref('');const valid=value=>{try{return new URL(value).protocol==='https:'}catch{return false}};function add(){if(!valid(url.value)){error.value='mirror.url_https';return}error.value='';emit('add',tool.value,url.value);tool.value='';url.value=''}function save(){if(Object.values(props.config).some(value=>!valid(value))){error.value='mirror.url_https';return}error.value='';emit('save')}const role=(name,value)=>/nodejs\.org|github\.com|golang\.org|go\.dev/.test(value)?'official':['node','go'].includes(name)?'configured':'mirror';const formatTime=value=>new Intl.DateTimeFormat(props.locale,{dateStyle:'medium',timeStyle:'medium'}).format(new Date(value));</script><style scoped>.mirror{display:grid;grid-template-columns:120px 1fr auto auto;gap:8px;align-items:center;padding:12px 0;border-bottom:1px solid var(--xdev-border-subtle)}.result{display:flex;gap:8px;align-items:center;grid-column:2/-1}.add{display:flex;gap:8px;align-items:center;flex-wrap:wrap}input{min-width:0}[role=alert]{color:var(--xdev-error)}@media(max-width:700px){.mirror{grid-template-columns:1fr}.result{grid-column:auto}.add{align-items:stretch;flex-direction:column}}</style>
